from pathlib import Path

p = Path('src/conv.rs')
s = p.read_text()

anchor = '''    #[inline]\n    fn unify<const RIGID: bool>(&mut self, depth: u32, x: V<'t>, y: V<'t>) -> bool {\n        let x = self.force_thunk(depth, x);\n        let y = self.force_thunk(depth, y);\n        if std::ptr::eq(x, y) {\n            return true;\n        }\n        self.unify_general::<RIGID>(depth, x, y)\n    }\n'''
assert anchor in s
replacement = '''    #[inline]\n    fn certified_semantic_ref_eq(&self, x: V<'t>, y: V<'t>) -> bool {\n        match (x, y) {\n            (Value::NatLit { ptr: px, .. }, Value::NatLit { ptr: py, .. }) => px == py,\n            (Value::StrLit { ptr: px, .. }, Value::StrLit { ptr: py, .. }) => px == py,\n\n            (\n                Value::Rigid { head: hx, spine: sx, .. },\n                Value::Rigid { head: hy, spine: sy, .. },\n            ) if std::ptr::eq(*sx, *sy) => match (*hx, *hy) {\n                (RigidHead::BVar(a, _), RigidHead::BVar(b, _)) => a == b,\n                (RigidHead::Axiom(nx, lx), RigidHead::Axiom(ny, ly))\n                | (RigidHead::Ctor(nx, lx), RigidHead::Ctor(ny, ly))\n                | (RigidHead::Recursor(nx, lx), RigidHead::Recursor(ny, ly))\n                | (RigidHead::QuotConst(nx, lx), RigidHead::QuotConst(ny, ly))\n                | (RigidHead::Inductive(nx, lx), RigidHead::Inductive(ny, ly)) => nx == ny && lx == ly,\n                _ => false,\n            },\n\n            (\n                Value::Pi { domain: dx, body: bx, .. },\n                Value::Pi { domain: dy, body: by, .. },\n            ) => bx.body == by.body\n                && std::ptr::eq(*dx, *dy)\n                && Self::envs_ptr_equal(bx.env, by.env),\n\n            (Value::Lam { body: bx, .. }, Value::Lam { body: by, .. }) =>\n                bx.body == by.body && Self::envs_ptr_equal(bx.env, by.env),\n\n            _ => false,\n        }\n    }\n\n    #[inline]\n    fn unify<const RIGID: bool>(&mut self, depth: u32, x: V<'t>, y: V<'t>) -> bool {\n        if std::ptr::eq(x, y) || self.certified_semantic_ref_eq(x, y) {\n            return true;\n        }\n        let x = self.force_thunk(depth, x);\n        let y = self.force_thunk(depth, y);\n        if std::ptr::eq(x, y) || self.certified_semantic_ref_eq(x, y) {\n            return true;\n        }\n        self.unify_general::<RIGID>(depth, x, y)\n    }\n'''
s = s.replace(anchor, replacement)
p.write_text(s)
print('applied MSI certified semantic ref v19')
